// Synthetic local performance and null audio only.
(() => {
  if(location.hostname!=='127.0.0.1'||window.__cicadaSoundContextSmoke)return;
  window.__cicadaSoundContextSmoke=true;
  const key='cicada.sound-context-proof',retained=JSON.parse(sessionStorage.getItem(key)||'null'),checks=retained?.checks||[];
  const read=async(name='state')=>{const r=await fetch('/api/'+name,{cache:'no-store'});if(!r.ok)throw new Error(name+': '+r.status);return r.json();};
  const wait=async(check,label)=>{const end=performance.now()+45000;while(performance.now()<end){if(await check())return;await new Promise(r=>setTimeout(r,50));}throw new Error('Timed out: '+label);};
  const ready=()=>wait(()=>window.__gosx?.ready&&document.querySelector('#studio-shell[data-shell-actions=ready]')&&!document.querySelector('form[data-gosx-form-state=pending],form[data-gosx-form-state=submitting]'),'Studio ready');
  const saved=source=>wait(async()=>(await read()).source===source&&document.querySelector('#undo-form [name=revision]')?.value===(await read()).revision,'saved score');
  const fill=(field,value)=>{field.value=value;field.dispatchEvent(new Event('input',{bubbles:true}));field.dispatchEvent(new Event('change',{bubbles:true}));};
  const choice=()=>document.querySelector('#cicada-pattern-preview [data-pattern-preview-track]');
  const query=()=>new URL(location.href).searchParams;
  async function upper(){await ready();await wait(()=>document.querySelector('#cicada-pattern-preview[data-sounds-ready=true]'),'sound engine');fill(choice(),'upper');await wait(()=>query().get('track')==='upper'&&document.querySelector('.performance-inspector [name=track]')?.value==='upper','new sound reaches note editing');}
  async function audition(){const button=document.querySelector('#cicada-pattern-preview [data-sound-preview]');await wait(()=>!button.disabled,'audition ready');button.click();await wait(()=>button.getAttribute('aria-pressed')==='true'&&button.getAttribute('aria-busy')==='false'&&/with upper/.test(document.querySelector('#cicada-pattern-preview [data-sound-status]').textContent),'chosen sound audition acknowledged');button.click();await wait(()=>button.getAttribute('aria-pressed')==='false'&&button.getAttribute('aria-busy')==='false','audition stopped');}
  async function render(label){document.querySelector('[data-gosx-disclosure-target="#export-dialog"]').click();const previous=(await read('export')).id;document.querySelector('#export button[type=submit]').click();let job;await wait(async()=>{job=await read('export');if(job.state==='failed')throw new Error(job.error);return job.id!==previous&&['succeeded','shortfall'].includes(job.state);},'WAV export');const r=await fetch(job.downloadURL),bytes=new Uint8Array(await r.arrayBuffer());if(!r.ok||new TextDecoder().decode(bytes.slice(0,4))!=='RIFF')throw new Error('Invalid WAV');const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');if(typeof window.__cicadaContextAudio==='function'){let binary='';for(const b of bytes)binary+=String.fromCharCode(b);await window.__cicadaContextAudio(label,btoa(binary));}document.querySelector('#export-dialog [data-gosx-disclosure-close]').click();return {hash,bytes:bytes.length};}
  (async()=>{
    await ready();const initial=(await read()).source,audio=await read('audio/config');if(!initial.includes('cicada-sound-context-test: disposable fixture')||audio.options.inputEnabled||String(audio.inventory.backendName||audio.inventory.backend).toLowerCase()!=='null')throw new Error('Use the disposable null-audio sound context score');
    if(query().get('pattern')!=='played'){location.href='/studio?dock=clip&pattern=played&note=0&scene=main&track='+(retained?'upper':'keys')+'&region=detail';return null;}
    if(retained?.phase==='reopen'){await saved(retained.final);if(choice().value!=='upper'||query().get('track')!=='upper')throw new Error('Reload lost the chosen sound');const reopened=await render('reopened');if(reopened.hash!==retained.exported.hash)throw new Error('Reopened WAV changed');sessionStorage.removeItem(key);checks.push('freshly loaded phrase keeps its chosen sound and exported WAV');return {type:'cicada-native-smoke',ok:true,...retained,phase:'done',checks,reopened};}
    await ready();const code=document.querySelector('#score textarea'),codeValue=code.value,draft=codeValue+'\n// Unsaved comparison draft\n',note=document.querySelector('.performance-inspector [name=velocity]'),velocity=note.value;
    fill(code,draft);fill(note,'95');const historyLength=history.length,beforeTransport=await read('transport');
    const management=document.querySelector('[data-pattern-management=played]');if(!management.open)management.querySelector('summary').click();const destination=[...management.querySelectorAll('form')].find(f=>f.querySelector('[name=action]')?.value==='bind').querySelector('[name=track]');fill(destination,'keys');
    await upper();
    if(code!==document.querySelector('#score textarea')||code.value!==draft||note!==document.querySelector('.performance-inspector [name=velocity]')||note.value!=='95'||history.length!==historyLength||destination.value!=='keys'||(await read()).source!==initial)throw new Error('Sound choice changed a draft, assignment, history or score');
    const during=await read('transport');if(during.playing!==beforeTransport.playing||during.bar!==beforeTransport.bar||during.step!==beforeTransport.step)throw new Error('Sound choice moved the song');
    checks.push('changing Hear with keeps mounted code and note drafts, explicit destinations, song position and browser history intact');
    if(typeof window.__cicadaContextViews==='function')await window.__cicadaContextViews();
    fill(code,codeValue);fill(note,velocity);
    await audition();
    const second=document.querySelectorAll('.performance-content tbody th a')[1];if(new URL(second.href).searchParams.get('track')!=='upper')throw new Error('Note selection link kept the old sound');second.click();await wait(()=>query().get('note')==='1'&&choice()?.value==='upper','note selection retains sound');await ready();
    const form=document.querySelector('.performance-inspector form');fill(form.querySelector('[name=pitch]'),'67');form.querySelector('button[type=submit]').click();await wait(async()=>/note 67 at=19ticks/.test((await read()).source),'note edited');await ready();if(choice().value!=='upper')throw new Error('Note save restored the old sound');
    document.querySelectorAll('.performance-content tbody th a')[0].click();await wait(()=>query().get('note')==='0'&&choice()?.value==='upper','first note retains sound');await ready();
    const point=document.querySelector('#note-gestures tbody th a');point.click();await ready();if(choice().value!=='upper')throw new Error('Gesture selection restored the old sound');
    const gesture=document.querySelector('#note-gestures form');fill(gesture.querySelector('[name=pressure]'),'0.6');gesture.querySelector('button[type=submit]').click();await wait(async()=>/pressure=0.6/.test((await read()).source),'gesture edited');await ready();if(choice().value!=='upper')throw new Error('Gesture save restored the old sound');
    document.querySelector('#shared-gestures tbody th a').click();await ready();if(choice().value!=='upper')throw new Error('Shared gesture selection restored the old sound');
    const shared=[...document.querySelectorAll('#shared-gestures form')].find(form=>form.querySelector('[name=action]')?.value==='shared-gesture');fill(shared.querySelector('[name=pressure]'),'0.7');shared.querySelector('button[type=submit]').click();await wait(async()=>/pressure=0.7/.test((await read()).source),'shared lane edited');await ready();if(choice().value!=='upper')throw new Error('Shared gesture save restored the old sound');
    const beforeScale=(await read()).source;document.querySelector('[data-performance-time=played] button[value="2/1"]').click();await wait(async()=>/pattern played performance length=7680ticks/.test((await read()).source),'time shaped');await ready();const final=(await read()).source;if(choice().value!=='upper')throw new Error('Time shaping restored the old sound');
    document.querySelector('#undo-form button').click();await saved(beforeScale);await ready();if(choice().value!=='upper')throw new Error('Undo restored the old sound');document.querySelector('#redo-form button').click();await saved(final);await ready();if(choice().value!=='upper')throw new Error('Redo restored the old sound');
    checks.push('note and gesture links, note/member/shared edits, time shaping and Undo/Redo keep the chosen sound');
    await audition();
    const exported=await render('edited');sessionStorage.setItem(key,JSON.stringify({phase:'reopen',checks,initial,final,exported}));location.href='/studio?dock=clip&pattern=played&note=0&scene=main&track=upper&region=detail';return null;
  })().catch(error=>({type:'cicada-native-smoke',ok:false,checks,error:String(error)+'\n'+String(error.stack||'')})).then(result=>{if(!result)return;if(typeof window.__cicadaContextResult==='function')window.__cicadaContextResult(result);else window.chrome?.webview?.postMessage(JSON.stringify(result));});
})();
